import React, { useEffect, useState, useContext } from 'react';
import { Row, Col, Card, Badge, ListGroup } from 'react-bootstrap';
import axios from 'axios';
import { AuthContext } from '../context/AuthContext';
import { io } from 'socket.io-client';

function Dashboard() {
  const { user, token } = useContext(AuthContext);
  const [stats, setStats] = useState({});
  const [circulars, setCirculars] = useState([]);

  useEffect(() => {
    const fetchStats = async () => {
      try {
        const res = await axios.get('http://localhost:5000/api/dashboard/stats', {
          headers: { Authorization: `Bearer ${token}` }
        });
        setStats(res.data);
      } catch (error) {
        console.error(error);
      }
    };

    const fetchCirculars = async () => {
      try {
        const res = await axios.get('http://localhost:5000/api/circulars', {
          headers: { Authorization: `Bearer ${token}` }
        });
        setCirculars(res.data);
      } catch (error) {
        console.error(error);
      }
    };

    if (token) {
      fetchStats();
      fetchCirculars();
    }
  }, [token]);

  useEffect(() => {
    const socket = io('http://localhost:5000');

    socket.on('new_circular', (circular) => {
      // Show notification or update local state
      alert(`New Circular: ${circular.title}`);
      setCirculars((prev) => [circular, ...prev]);
    });

    return () => socket.disconnect();
  }, []);

  return (
    <div>
      <h2 className="mb-4">Welcome, {user?.name}</h2>

      {user?.role === 'Admin' && (
        <Row className="mb-4">
          <Col md={4}>
            <Card className="bg-primary text-white shadow">
              <Card.Body>
                <Card.Title>Total Circulars</Card.Title>
                <Card.Text className="display-4">{stats.totalCirculars || 0}</Card.Text>
              </Card.Body>
            </Card>
          </Col>
          <Col md={4}>
            <Card className="bg-success text-white shadow">
              <Card.Body>
                <Card.Title>Total Users</Card.Title>
                <Card.Text className="display-4">{stats.totalUsers || 0}</Card.Text>
              </Card.Body>
            </Card>
          </Col>
          <Col md={4}>
            <Card className="bg-info text-white shadow">
              <Card.Body>
                <Card.Title>New Users (7 days)</Card.Title>
                <Card.Text className="display-4">{stats.newUsers || 0}</Card.Text>
              </Card.Body>
            </Card>
          </Col>
        </Row>
      )}

      {(user?.role === 'Student') && (
         <Row className="mb-4">
           <Col md={6}>
             <Card className="bg-primary text-white shadow">
               <Card.Body>
                 <Card.Title>Relevant Circulars</Card.Title>
                 <Card.Text className="display-4">{stats.relevantCirculars || 0}</Card.Text>
               </Card.Body>
             </Card>
           </Col>
           <Col md={6}>
             <Card className="bg-danger text-white shadow">
               <Card.Body>
                 <Card.Title>Unread</Card.Title>
                 <Card.Text className="display-4">{stats.unreadCount || 0}</Card.Text>
               </Card.Body>
             </Card>
           </Col>
         </Row>
      )}

      <h4>Recent Circulars</h4>
      <Card className="shadow">
        <ListGroup variant="flush">
          {circulars.map(circular => (
            <ListGroup.Item key={circular._id} className="d-flex justify-content-between align-items-center p-3">
              <div>
                <h5 className="mb-1">{circular.title}</h5>
                <p className="mb-1 text-muted">{circular.description}</p>
                <small>By: {circular.createdBy?.name || 'Unknown'} | {new Date(circular.createdAt).toLocaleDateString()}</small>
              </div>
              <Badge bg={circular.priority === 'Urgent' ? 'danger' : 'info'} pill>
                {circular.priority}
              </Badge>
            </ListGroup.Item>
          ))}
          {circulars.length === 0 && (
            <ListGroup.Item className="p-4 text-center text-muted">
              No circulars found.
            </ListGroup.Item>
          )}
        </ListGroup>
      </Card>
    </div>
  );
}

export default Dashboard;
